#!/bin/sh
# Lists (dry run, default) or deletes PROfit cache files (*.bin) larger than SIZE MB and older than DAYS days under runs/.
# Caches are regenerated by PROfit `process`; ROOT outputs and results/*.json are never touched. Usage: scripts/clean_runs.sh [SIZE_MB=500] [DAYS=7] [--delete]
SIZE=${1:-500}; DAYS=${2:-7}; cd "$(dirname "$0")/.." || exit 1
echo "candidates (*.bin > ${SIZE} MB, older than ${DAYS} days) under runs/ :"
find runs -type f -name '*.bin' -size +"${SIZE}"M -mtime +"${DAYS}" -exec ls -l {} + | awk '{s+=$5; printf "%8.1f GB  %s\n", $5/1e9, $9} END {printf "total %.1f GB\n", s/1e9}'
if [ "$3" = "--delete" ] || [ "$1" = "--delete" ]; then printf "Delete these files? [yes/NO] "; read a; [ "$a" = "yes" ] && find runs -type f -name '*.bin' -size +"${SIZE}"M -mtime +"${DAYS}" -delete && echo deleted; fi
